/**
 * 字体（子集化的开源字体，base64 内联，不依赖任何 CDN）
 *
 * 中文：Noto Sans SC（思源黑体）可变字体，只保留界面用到的 879 个字
 *       授权：SIL Open Font License 1.1，可商用
 * 英文/数字：Space Grotesk 500 / 700，只保留 ASCII
 *       授权：SIL Open Font License 1.1，可商用
 *
 * 为什么要子集化：完整中文字体 10MB 以上，小程序单包只有 2MB。
 * 只留用到的字，248KB 就能装下，而且是可变字体，100~900 的字重都能用。
 */

var ZH = 'data:font/woff2;base64,';
var SG5 = 'data:font/woff2;base64,';
var SG7 = 'data:font/woff2;base64,';

var loaded = { zh: false, en: false };

function load() {
  loadOne('LJSans', ZH, 'zh');
  loadOne('LJGrotesk', SG5, 'en', '500');
  loadOne('LJGrotesk', SG7, 'en', '700');
}

function loadOne(family, data, key, weight) {
  try {
    wx.loadFontFace({
      global: true,
      family: family,
      source: 'url("' + data + '")',
      desc: weight ? { weight: weight } : {},
      success: function () {
        loaded[key] = true;
        console.log('[font] ' + family + (weight ? ' ' + weight : '') + ' 已加载');
      },
      fail: function (e) {
        // 加载失败就回落到系统字体，不影响使用
        console.warn('[font] ' + family + ' 加载失败', e);
      }
    });
  } catch (e) {
    console.warn('[font] loadFontFace 不可用，使用系统字体', e);
  }
}

module.exports = { load: load, loaded: loaded };
